mapper.select:
select p.user_id userId, d.avatar, d.nickname, st_distance(p.pt, point(#{user.lng},#{user.lat}))*111.195 distance, d.date_status dateStatus, p.uptime timeShow, if(d.avatar_status = 'influencer','influencer',if(d.vip_status = '1',d.vip_expire,'-')) avatarStatus from corgi_user_position p left join corgi_user_detail d on d.user_id = p.user_id where p.user_id != #{user.userId}
and p.uptime > #{timestamp}
and not exists (select 1 from corgi_user_match m where m.user_id = #{user.userId} and m.match_id = p.user_id and status = '1') and not exists (select 1 from corgi_user_match_view v where v.user_id = #{user.userId} and v.match_id = p.user_id and status = '1') order by distance limit #{size};

select p.user_id userId, d.avatar, d.nickname, st_distance(p.pt, point(#{user.lng},#{user.lat}))*111.195 distance, d.date_status dateStatus, p.uptime timeShow, if(d.avatar_status = 'influencer','influencer',if(d.vip_status = '1',d.vip_expire,'-')) avatarStatus from corgi_user_position p left join corgi_user_detail d on d.user_id = p.user_id where p.user_id != #{user.userId}
${user.result}
and not exists (select 1 from corgi_user_match m where m.user_id = #{user.userId} and m.match_id = p.user_id and status = '1') and not exists (select 1 from corgi_user_match_view v where v.user_id = #{user.userId} and v.match_id = p.user_id and status = '1') order by p.uptime desc limit #{size};

